U.add('snd','adv_counter',{sev:6.68,ax:{x:0.796,a:0.997},new:'mechanical counter: silent until a click, then a ratchet of small ticks for each digit that turns',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv;const bp=a.createBiquadFilter();bp.type='bandpass';bp.frequency.value=Q.counter_hz;bp.Q.value=2;bp.connect(o);
 R.on(document,'pointerdown',()=>{for(let i=0;i<Q.counter_n;i++)R.to(()=>{const s=R.src(U.au.noise(a,.02)),g=a.createGain(),t=a.currentTime;g.gain.setValueAtTime(Q.counter_gain,t);g.gain.exponentialRampToValueAtTime(.0001,t+.012);s.connect(g).connect(bp);s.start(t)},i*Q.counter_step)});return()=>R.stop()}});
U.add('snd','adv_seekdrift',{sev:6.11,ax:{x:0.653,a:0.995},new:'two sines that start in unison and drift apart in cents over several minutes, beating slower then faster',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv,t=a.currentTime;[0,1].forEach(i=>{const s=R.osc('sine',Q.drift_hz),g=a.createGain();g.gain.value=Q.drift_gain;s.detune.setValueAtTime(0,t);s.detune.linearRampToValueAtTime(i?Q.drift_cents:0,t+Q.drift_s);s.connect(g).connect(o);s.start()});return()=>R.stop()}});
U.add('nav','adv_copynote',{sev:6.76,ax:{x:0.816,n:0.982,v:0.997},desc:'what you copy is not all that you copy',new:'copying text puts a hidden backstory fragment on the clipboard after what was selected',apply:c=>U.on(document,'copy',e=>{try{const s=String(getSelection()||'');if(!s)return;e.clipboardData.setData('text/plain',s+'\n\n-- '+U.loreAt(c,13));e.preventDefault()}catch(_){}})});
U.add('nav','adv_keyrefuse',{sev:6.28,ax:{x:0.694,n:0.969,v:0.995},desc:'escape is a key, not an exit',new:'pressing Escape is answered with a line saying it is not an exit, a different line each press',apply:c=>{let n=0;const L=['Escape is not an exit. It is a key I kept for you.','You pressed Escape. The fan got a little louder.','Escape was in the original design. It was the first thing removed.','Nobody has ever used Escape here. You are not nobody.','Escape goes back. There is no back. There is this.'];U.on(document,'keydown',e=>{if(e.key!='Escape')return;let p=c.w.querySelector('.esc');if(!p){p=U.tag('p','font:12px Courier New,monospace;opacity:.75;margin:8px 0 0');p.className='truth esc';c.w.append(p)}p.textContent=L[n++%L.length]})}});